const { test, expect } = require('@playwright/test');

test('should create deal prospect and verify appointment slot lock', async ({ page }) => {
  await page.goto('/dashboard/deals');
  await page.getByRole('button', { name: /new deal/i }).click();
  await page.getByLabel('Customer Name').fill('Test Buyer');
  await page.getByLabel('Phone').fill('+923099731256');
  await page.getByRole('button', { name: /save deal/i }).click();
  await expect(page.getByText('Deal created successfully')).toBeVisible();
});
